 public static void BakeMenuAndInspect(){
  var gs=EditorSceneManager.OpenScene(GS);var casino=All(gs).Select(t=>t.GetComponent<ParkCasinoIntegration>()).First(c=>c);var cs=EditorSceneManager.OpenScene("Assets/SushiAndFish/Casino/Imported/Scenes/CasinoScene.unity",OpenSceneMode.Additive);var volumes=All(cs).Select(t=>t.GetComponent<LightVolume>()).Where(v=>v).ToArray();var lv=volumes.FirstOrDefault(v=>v.lightMap&&(v.fileName.Contains("Outside")||v.lightMap.name.Contains("Outside")));if(!lv)throw new Exception("Original outside light volume not found: "+string.Join(";",volumes.Select(v=>v.fileName+" / "+v.lightMap?.name)));
