 public static void InspectContacts(){var receipt=new ContactReceipt{utc=DateTime.UtcNow.ToString("o")};var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);var nodes=All(gs).Concat(All(ds)).ToArray();foreach(var root in nodes.Select(t=>t.GetComponent<DressingSceneRoot>()).Where(r=>r))root.ActivateAllImmediate();Physics.SyncTransforms();foreach(var t in nodes.Where(t=>t.GetComponent<MeshRenderer>()&&(t.name.StartsWith("SM_fence")||t.name.StartsWith("Railing")))){var mesh=t.GetComponent<MeshFilter>()?.sharedMesh;if(!mesh||!(P(t).StartsWith("Restored")||P(t).StartsWith("SourceCoast")||P(t).StartsWith("Root/DockSide/")||P(t).StartsWith("Root/Comps/Comp9")||P(t).StartsWith("Root/Comps/Comp11")))continue;receipt.guardrails++;var points=mesh.vertices.Where(v=>v.y<=mesh.bounds.min.y+.015f).Select(t.TransformPoint).GroupBy(v=>Mathf.RoundToInt(v.x/.03f)+","+Mathf.RoundToInt(v.z/.03f)).Select(g=>new Vector3(g.Average(v=>v.x),g.Min(v=>v.y),g.Average(v=>v.z)));foreach(var p in points){float floor=float.NegativeInfinity;foreach(var hit in Physics.RaycastAll(new Vector3(p.x,Mathf.Max(4.8f,p.y+2),p.z),Vector3.down,20,~0,QueryTriggerInteraction.Ignore)){if(hit.transform==t||hit.transform.IsChildOf(t)||hit.normal.y<.6f||hit.transform.name.StartsWith("SM_fence")||hit.transform.name.StartsWith("Railing"))continue;floor=Mathf.Max(floor,hit.point.y);}receipt.testedRailFeet++;if(float.IsNegativeInfinity(floor)||p.y-floor>.14f)receipt.floating.Add(new ContactRow{path=P(t),point=p,floor=float.IsNegativeInfinity(floor)?-999:floor,gap=float.IsNegativeInfinity(floor)?999:p.y-floor});}}
  var maps=JsonUtility.FromJson<Maps>(File.ReadAllText(Path.Combine(Reports,"island-trim-edit-audit.json")));foreach(var terrain in nodes.Select(t=>t.GetComponent<Terrain>()).Where(t=>t)){var map=maps.terrains.FirstOrDefault(m=>m.path==P(terrain.transform));if(map==null)continue;var original=AssetDatabase.LoadAssetAtPath<TerrainData>(map.originalData);var p=terrain.transform.position;var size=terrain.terrainData.size;foreach(var r in nodes.Select(t=>t.GetComponent<MeshRenderer>()).Where(r=>r&&(r.name.StartsWith("SM_sidewalk")||r.name=="SideWalkTerrainEdge")&&r.bounds.max.y>2.9f&&r.bounds.max.y<3.5f)){var b=r.bounds;for(float z=b.min.z;z<=b.max.z;z+=1)for(float x=b.min.x;x<=b.max.x;x+=1){if(x<p.x||x>p.x+size.x||z<p.z||z>p.z+size.z)continue;var c=r.GetComponent<MeshCollider>();if(!c||!c.Raycast(new Ray(new Vector3(x,4,z),Vector3.down),out var hit,2))continue;float oh=p.y+original.GetInterpolatedHeight((x-p.x)/size.x,(z-p.z)/size.z);float ch=p.y+terrain.SampleHeight(hit.point);receipt.nativeSurfaceSamples++;if(oh>hit.point.y-.35f&&ch<hit.point.y-.35f){receipt.unsupportedRelativeToSource++;receipt.unsupported.Add(new ContactRow{path=P(r.transform),point=hit.point,originalTerrain=oh,currentTerrain=ch,gap=hit.point.y-ch});}}}}
  File.WriteAllText(Path.Combine(Reports,"screenshot-coast-contact.json"),JsonUtility.ToJson(receipt,true));EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");
 }
